#include <iostream>
#include <vector>
#include <string>

std::string s;
const std::string qq = "QAQ";
std::vector<std::vector<int>> arr;

int Q(int m, int n) {
    if (arr[n][m] != -1)
        return arr[n][m];
    if (m == 0)
        return 1;
    if (n == 0)
        return 0;

    int i = 0, j = 0;
    if (qq[m - 1] == s[n - 1])
        i = Q(m - 1, n - 1);

    j = Q(m, n - 1);
    arr[n][m] = i + j;
    return i + j;
}

int main() {
    std::cin >> s;
    int len = s.length();
    arr.assign(len + 1, std::vector<int>(4, -1));

    std::cout << Q(3, len) << std::endl;
    return 0;
}

